from p_common import *
# (family, short, title, symptom, evidence[], diagnosis, fix, where)
CASES = [
 (0, 'Copy', 'Changing a copy changed the original', 'After <code>var b = a; b.Name = "Ravi";</code> the name in <code>a</code> changed too.', ['<code>a</code> is a <b>class</b> instance.', 'Both variables print the same address in the debugger.'], 'Copying a reference copies the address, not the object.', 'Make a real copy (a <code>record</code> with <code>with</code>, or a struct / clone) when you want independence.', 'page 3'),
 (0, 'Boxing', 'A list of numbers is slow and creates lots of garbage', 'A loop adds 1,000,000 ints to an <code>ArrayList</code>; the GC runs constantly.', ['<code>ArrayList</code> stores <code>object</code>.', 'A profiler shows a million small objects.'], 'Boxing: every int becomes a heap object.', 'Use a generic <code>List&lt;int&gt;</code> — no boxes.', 'page 5'),
 (0, 'Overflow', 'The app crashes on a big input and cannot be caught', 'A recursive method works for 100 items and crashes for 100,000.', ['Crash says stack overflow.', 'The method calls itself once per item.'], 'Each call needs a stack frame; the stack is small and fixed.', 'Loop, or use an explicit collection, instead of deep recursion.', 'page 2'),
 (0, 'Param', 'The Reset method does nothing', '<code>void Reset(Person p) { p = new Person("Zed"); }</code> is called, but the caller’s person is unchanged.', ['The method assigns to the <b>parameter</b>.', 'The caller still prints the old name.'], 'The parameter is a copy of the address; assigning to it moves only the parameter’s own arrow.', 'Change the object’s fields, return the new object, or pass <code>ref</code> if the caller’s variable must change.', '[[p:parameters]], [[p:ref-out-in]]'),
 (1, 'Ctor', 'A base constructor sees a null field of the child', 'The base constructor calls a virtual method; the override prints the child’s field as null.', ['The child’s field initialiser has not run the constructor body yet.', 'Order: base constructor body → child constructor body.'], 'Calling a virtual method in a constructor runs the override before the child is fully built.', 'Do not call virtual members from constructors; use an init method after construction.', 'page 8'),
 (1, 'Closure', 'A 50 MB report never leaves memory', 'A handler <code>() =&gt; Log(report.Title)</code> is registered on a long-lived event. The report screen is closed but its data stays.', ['The lambda uses only <code>report.Title</code> but captures <code>report</code>.', 'The closure object is referenced by the event’s delegate.'], 'A capturing lambda keeps the whole captured object alive as long as the delegate is reachable.', 'Copy what you need into a local first (<code>var title = report.Title;</code>), use a static lambda, and unsubscribe.', '[[p:delegates-closures]]'),
 (2, 'Static', 'Memory grows all day and never drops', 'A <code>static Dictionary</code> caches every customer ever looked up.', ['Gen 2 keeps growing.', 'A heap snapshot shows the dictionary as the root.'], 'A static field is a GC root; nothing in the cache is ever removed.', 'Add a size limit or expiry, or use a proper memory cache.', 'pages 6, 17'),
 (2, 'Event', 'Closed screens stay in memory', 'After opening and closing 200 windows, memory still holds 200 window objects.', ['Each window subscribes to a long-lived service event with <code>+=</code>.', 'No <code>-=</code> anywhere.'], 'The publisher’s handler list keeps every subscriber reachable.', 'Unsubscribe in Close/Dispose, or use a weak-event pattern.', 'page 17'),
 (2, 'Locked', 'The file is still locked after reading it', 'A report reads a file, then another process cannot delete it for minutes.', ['<code>new StreamReader(path)</code> with no <code>using</code>.', 'The lock vanishes only after some time.'], 'The GC frees memory but does not close files; a finalizer is late.', 'Wrap in <code>using</code> so <code>Dispose</code> runs at the end of the block.', 'page 16'),
 (2, 'Buffers', 'Memory spikes and gen 2 collections are frequent', 'An API allocates a fresh 100 KB byte array for every request.', ['Allocations over 85,000 bytes.', 'Many gen 2 collections in the counters.'], 'Big arrays go to the LOH, which is collected with gen 2.', 'Rent the buffer from <code>ArrayPool</code> and return it.', 'pages 15, 21'),
 (3, 'Race', 'The counter is lower than expected with two threads', '1,000 increments on each of two threads gives about 1,700, not 2,000.', ['The counter is a shared field changed with <code>Value++</code>.', 'Result differs on each run.'], 'Read-modify-write on shared heap memory is not atomic.', '<code>Interlocked.Increment</code> or a <code>lock</code>.', 'page 18'),
 (3, 'Await', 'It will not compile: a Span cannot be used across await', 'Error: a <code>Span&lt;byte&gt;</code> local is used before and after an <code>await</code>.', ['The method is <code>async</code>.', '<code>Span</code> is a <code>ref struct</code>.'], 'Locals across an await live in a heap state machine; a ref struct cannot.', 'Use <code>Memory&lt;T&gt;</code> or <code>byte[]</code> across the await; use the Span inside non-async helper code.', 'pages 19, 21'),
 (3, 'Scoped', 'Works for the first request, then “disposed context” errors', 'A cache service registered as a singleton takes <code>AppDbContext</code> in its constructor.', ['The service is <code>AddSingleton</code>; the context is <code>AddScoped</code>.', 'Errors start after the first request ends.'], 'A captive dependency: the singleton holds a scoped object beyond its scope, so it is disposed and stale.', 'Make the service scoped, or inject <code>IServiceScopeFactory</code> and create a scope per use.', '[[p:di-lifetimes]]'),
]
FAM = ['Where it lives', 'Objects & types', 'GC & clearing', 'Threads, async & apps']

def d_board():
    d = Diagram('mcl', 640, 320, 'The memory clinic case board: thirteen cases in four families: where data lives, objects and types, garbage collection and clearing, and threads, async and apps')
    zones = [('WHERE IT LIVES', 'cyan', 8, 8, 380, 86), ('OBJECTS & TYPES', 'emerald', 396, 8, 236, 104), ('GC & CLEARING', 'amber', 8, 164, 380, 86), ('THREADS, ASYNC & APPS', 'violet', 396, 164, 236, 68)]
    for gi, (t, col, x, y, w, bw) in enumerate(zones):
        d.zone(x, y, w, 144, col, t)
        for k, c in enumerate([c for c in CASES if c[0] == gi]):
            num = CASES.index(c) + 1
            d.box(x + 8 + k * (bw + 4), y + 38, bw, 86, [(f'Case {num}', 't'), (c[1], 's')], col)
    return d

def build_memory_clinic():
    b = ''
    b += see(figure(d_board(), 'thirteen small cases in four families: <b>where it lives</b> (1–4), <b>objects &amp; types</b> (5–6), <b>GC &amp; clearing</b> (7–10) and <b>threads, async &amp; apps</b> (11–13). Each shows a symptom and the evidence you would really see. <b>Decide first</b>, then reveal the answer.'))
    b += one('You have followed memory from the stack to the garbage collector and async. This is the practice ward: <b>symptom → evidence → which memory place → fix → where to review</b>.')
    b += block('🧭 How to decide', '    <p>Ask in this order: <b>where does this data live</b> (stack, heap, static)? → <b>who holds a reference to it</b> (a root: stack, static, event)? → <b>who is supposed to clear it</b> (method return, GC, Dispose)? → <b>is more than one thread involved</b>?</p>', label_cls='why', id_='why')
    for n, (zi, short, title, sym, ev, dg, fx, ref) in enumerate(CASES, 1):
        evh = '<ul>' + ''.join(f'<li>{e}</li>' for e in ev) + '</ul>'
        ans = f'<p><b>Diagnosis.</b> {dg}</p><p><b>Fix.</b> {fx}</p><p>📖 <b>Where to review:</b> {ref}.</p>'
        inner = (f'    <div class="kd-card"><h4>{title}</h4><p><b>Symptom.</b> {sym}</p><p><b>Evidence.</b></p>{evh}'
                 f'<p><b>Your move:</b> what is really happening in memory?</p>'
                 f'<details class="zoom"><summary><span class="chev">▾</span> Reveal the answer</summary><div class="zoom-inner">{ans}</div></details></div>')
        b += block(f'🩺 Case {n}', inner, label_cls='see' if zi % 2 == 0 else 'why')
    b += block('🗺️ Answer key', table(['Case', 'Family', 'Cause', 'Review'], [[f'{i}. {c[2]}', FAM[c[0]], c[5], c[7]] for i, c in enumerate(CASES, 1)]), label_cls='see')
    b += block('🎬 How you did', scenarios([('🟢', '10–13 before the reveal', 'You think in memory places and references. Keep checking the roots.', 'Apply it'), ('🟡', '6–9', 'You know the pieces; practise asking “who holds a reference?”.', 'Re-read GC basics'), ('🔴', '0–5', 'Normal at first. Re-read the memory map and the stack-vs-heap pages.', 'Start at page 1')]), label_cls='saythis')
    b += recall(['Method: where does it live → who references it → who clears it → how many threads?', 'Leaks are references: statics, events, caches, undisposed resources.', 'Allocate less: generics, pools, Span.', 'Shared heap data + threads = races.'])
    b += saythis('“I read a memory problem by asking where the data lives, what still references it, who is supposed to clear it and whether threads share it — then I fix the reference, the lifetime or the allocation, and measure again.”')
    b += trap(['<b>Calling GC.Collect() to “fix” memory.</b> Find the reference that keeps it alive.', '<b>Tuning GC modes before measuring.</b> Most problems are references and allocations in your code.'])
    b += next_box('That completes the .NET Memory Lab. Go back to the hub to revisit any page, or explore the SOLID and Design Patterns labs.', '../index.html', '.NET Memory Lab hub')
    b += fact_note('Every case is explained, with its sources, on the page it points to. The cases and numbers are illustrative.', [DOC_GC, DOC_DISPOSE])
    return page('memory-clinic', 'Capstone: the .NET Memory Clinic', f'Concept {pnum("memory-clinic")} of {ptotal()} · ⚙️ Tuning & judgement', 'Thirteen small cases: <span class="grad-text">find where it lives, who holds it, who clears it</span>.', 'A practice ward for the whole lab: symptom, evidence, your diagnosis, then reveal — with an answer key back to each page.', 'Here is a memory symptom. Where does the data live, what still references it, and who clears it?', b, CR + ['<span class="cur">Memory clinic</span>'], '')
